const FX={st:'idle',at:0,data:null,err:null,busy:false};
const isFlow=()=>M[cur]&&M[cur].k==='v7'&&M[cur].pg==='flow';
async function fxLoad(){if(FX.busy)return;FX.busy=true;try{const r=await fetch('/api/market/fxflow',{cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);const j=await r.json();if(!j||!Array.isArray(j.currencies))throw new Error(j&&j.error?String(j.error):'format data tidak dikenal');FX.data=j;FX.st='ok';FX.err=null}catch(e){FX.st='err';FX.err=String(e&&e.message||e)}FX.at=Date.now();FX.busy=false;if(isFlow())rd()}
setInterval(()=>{if(isFlow()&&!FX.busy&&!document.hidden&&Date.now()-FX.at>=(FX.err?10000:30000))fxLoad()},5000);
const FTO=['m15','h1','h4','d1','w1','m1'],FTL={m15:'15m',h1:'1H',h4:'4H',d1:'1D',w1:'1W',m1:'1M'};
const f2=v=>{if(!isN(v))return '—';const t=Math.abs(v).toFixed(2);return (t==='0.00'?'':v>0?'+':'-')+t+'%'};
const sg=v=>!isN(v)||v===0?'m':v>0?'g':'r';
