const usOpen=()=>{try{const p=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',hour:'numeric',minute:'numeric',hour12:false}).formatToParts(new Date()),g=t=>(p.find(x=>x.type===t)||{}).value,m=(+g('hour')%24)*60+(+g('minute'));return !['Sat','Sun'].includes(g('weekday'))&&m>=570&&m<960}catch(e){return true}};
const VOLX={XAU:1.5,DXY:.5,TOTAL:3,SPY:1.5,VXUS:1.5,VNQ:1.5,USO:3,LQD:.5};
const aSc=(a,tf)=>{const v=a.chg&&a.chg[tf],n=((FX.data||{}).norm||{})[tf];return isN(v)&&n?Math.round(100*Math.tanh(v/(n*(VOLX[a.id]||1)))):null};
const aOf=id=>((FX.data||{}).assets||[]).find(a=>a.id===id)||null;
const fxEnt=()=>{const d=FX.data;if(!d)return[];const o=(d.currencies||[]).map(c=>({id:c.code,label:c.code,perf:c.perf||{},score:c.score||{}}));(d.assets||[]).filter(a=>a.id==='XAU'||a.id==='BTC').forEach(a=>{if(a.perf&&a.score)o.push({id:a.id,label:a.id,perf:a.perf,score:a.score})});return o};
function fxLab(e,tf){const s=e.score[tf];if(!isN(s))return['nn','—'];const a=Math.abs(s),up=s>0;if(a<10)return['nn',S('NETRAL','NEUTRAL')];const nt=FTO[FTO.indexOf(tf)+1],ns=nt?e.score[nt]:null;if(isN(ns)&&Math.abs(ns)>=10&&(ns>0)!==up)return[up?'go':'ro',up?S('MULAI MASUK','STARTING IN'):S('MULAI KELUAR','STARTING OUT')];if(a>=50)return[up?'gs':'rs',up?S('MASUK KUAT','STRONG IN'):S('KELUAR KUAT','STRONG OUT')];return[up?'g1':'r1',up?S('MASUK','IN'):S('KELUAR','OUT')]}
