function fxSankey(cols,links){const nw=fxNarrow(),ww=c=>Math.max(...c.map(x=>((x.n||'')+' '+(x.t||'')).length)),LM=nw?100:Math.min(260,Math.max(90,ww(cols[0])*6.8+16)),RM=nw?100:Math.min(260,Math.max(90,ww(cols[cols.length-1])*6.8+16)),W=nw?360:Math.max(760,LM+RM+400),P=nw?4:6,NW=10,MH=nw&&cols.some(c=>c.some(x=>x.s))?26:13,n=cols.length,tot=Math.max(...cols.map(c=>c.reduce((s,x)=>s+x.v,0)))||1,K=(nw?240:280)/tot,xs=cols.map((_,i)=>LM+(W-LM-RM-NW)*i/(n-1));cols.forEach(c=>c.forEach(x=>{x.h=Math.max(x.v*K,MH)}));const hs=cols.map(c=>c.reduce((s,x)=>s+x.h,0)+P*(c.length-1)),H=Math.max(...hs)+30;cols.forEach((c,ci)=>{let y=(H-hs[ci])/2;c.forEach(x=>{x.y=y;x.x=xs[ci];x.oo=0;x.io=0;y+=x.h+P})});let s='';links.slice().sort((p,r)=>p.a[0]-r.a[0]||p.a[1]-r.a[1]||p.b[1]-r.b[1]).forEach(l=>{const A=cols[l.a[0]][l.a[1]],B=cols[l.b[0]][l.b[1]],h=l.v*K;if(!(h>0))return;const x0=A.x+NW,x1=B.x,m=(x0+x1)/2,y0=A.y+A.oo,y1=B.y+B.io;A.oo+=h;B.io+=h;s+=`<path d="M${x0},${y0}C${m},${y0} ${m},${y1} ${x1},${y1}L${x1},${y1+h}C${m},${y1+h} ${m},${y0+h} ${x0},${y0+h}Z" fill="${l.c}" fill-opacity=".38"><title>${E(l.t||'')}</title></path>`});let nd='';cols.forEach((c,ci)=>c.forEach(x=>{const f=ci===0;nd+=`<rect x="${x.x}" y="${x.y}" width="${NW}" height="${x.h}" rx="3" fill="${x.c}"/><text x="${f?x.x-6:x.x+NW+6}" y="${x.y+x.h/2+4}" text-anchor="${f?'end':'start'}" dy="${x.s&&fxNarrow()?-5:0}" font-size="12" fill="#e9dfcf" style="paint-order:stroke;stroke:#241810;stroke-width:3px">${E(x.n)} ${E(x.t||'')}</text>${x.s&&fxNarrow()?`<text x="${f?x.x-6:x.x+NW+6}" y="${x.y+x.h/2+4}" dy="7" text-anchor="${f?'end':'start'}" font-size="9.5" fill="#b9ac96" style="paint-order:stroke;stroke:#241810;stroke-width:3px">${E(String(x.s).length>20?String(x.s).slice(0,19)+'\u2026':x.s)}</text>`:''}`}));return `<svg class="fxsv" viewBox="0 0 ${W} ${H}">${s}${nd}</svg>`}
function fxSk(it){const N=it.filter(x=>x.z<0).sort((a,b)=>a.z-b.z).map(x=>({n:x.n,v:-x.z,s:x.s,t:x.t,c:'#f0826c'})),P=it.filter(x=>x.z>0).sort((a,b)=>b.z-a.z).map(x=>({n:x.n,v:x.z,s:x.s,t:x.t,c:'#5fd68a'}));if(!N.length||!P.length)return `<div class="m">${S('Belum ada pasangan turun dan naik pada timeframe ini.','No falling and rising pair on this timeframe.')}</div>`;const tn=N.reduce((s,x)=>s+x.v,0),tp=P.reduce((s,x)=>s+x.v,0),mx=Math.max(tn,tp),links=[];N.forEach((a,i)=>P.forEach((b,j)=>links.push({a:[0,i],b:[1,j],v:a.v*b.v/mx,c:'#d9a441',t:a.n+' → '+b.n})));return `<div style="display:flex;justify-content:space-between;margin:4px 0;font-size:12px;letter-spacing:1px"><span class="r">${S('KELUAR','OUT')}</span><span class="g">${S('MASUK','IN')}</span></div>${fxSankey([N,P],links)}`}
function fxP1(tf){const L=fxEnt().filter(e=>isN(e.score[tf])).sort((a,b)=>b.score[tf]-a.score[tf]);if(!L.length)return `<div class="m">${S('Data belum tersedia untuk timeframe ini.','No data for this timeframe.')}</div>`;return L.map(e=>{const s=e.score[tf],lb=fxLab(e,tf);return `<div class="fxr"><b style="color:var(--w)">${E(e.label)}</b><div class="fxb"><u></u><i style="${s>=0?'left:50%':'right:50%'};width:${Math.abs(s)/2}%;background:var(${s>=0?'--g':'--r'})"></i></div><span class="${sg(e.perf[tf])}" style="text-align:right">${f2(e.perf[tf])}</span><span class="fxp ${lb[0]}">${lb[1]}</span></div>`}).join('')}
